const item = $input.first().json;
const status = (item.status || '').toLowerCase();
// Polls are counted PER SCENE in static data, not with $runIndex — which
// counts every poll of the execution across all scenes, and a pass now
// covers the whole film (Sort & Cap Scenes resets sd.polls each pass).
// 30s a poll ('Wait Video'); 120 = one hour a clip, sized for the
// low-priority Veo queue. A clip that overruns it is treated as a FAILED
// job — 'Resubmit Guard' resubmits it — rather than killing the film.
const sd = $getWorkflowStaticData('global');
sd.polls = sd.polls || {};
const sceneId = $('Current Scene').first().json.id;
sd.polls[sceneId] = (sd.polls[sceneId] || 0) + 1;
const MAX_POLLS = 120;
const raw = JSON.stringify(item);
const done = status === 'completed' || raw.includes('flow-content.google/video');
let failed = status === 'failed' || status === 'error' || status === 'cancelled';
if (!done && !failed && sd.polls[sceneId] > MAX_POLLS) {
  console.log('Scene ' + sceneId + ': video job still not done after ' + MAX_POLLS + ' polls — treating as failed so it gets resubmitted.');
  failed = true;
  item.error = 'polling timed out after ' + MAX_POLLS + ' polls';
}
// Failed jobs are routed to a resubmit branch instead of throwing here —
// Google intermittently fails generations with VIDEO_GENERATION_TIMED_OUT
// and a resubmit usually succeeds.
return [{ json: Object.assign({}, item, { done: done && !failed, jobFailed: failed }) }];

const item = $input.first().json;
function find(obj, pred) {
  let f = null;
  (function w(o) { if (f) return;
    if (typeof o === 'string') { if (pred(o)) f = o; return; }
    if (Array.isArray(o)) { for (const v of o) { if (f) return; w(v); } return; }
    if (o && typeof o === 'object') { for (const k of Object.keys(o)) { if (f) return; w(o[k]); } }
  })(obj);
  return f;
}
let url = null, mediaId = null;
try { const gv = item.response && item.response.media && item.response.media[0] && item.response.media[0].video && item.response.media[0].video.generatedVideo; if (gv) { if (typeof gv.fifeUrl === 'string') url = gv.fifeUrl; if (typeof gv.mediaGenerationId === 'string') mediaId = gv.mediaGenerationId; } } catch (e) {}
if (!url) url = find(item, s => s.startsWith('http') && s.includes('flow-content.google') && s.includes('/video'));
if (!mediaId) mediaId = find(item, s => s.includes('-video:'));
if (!url && !mediaId) throw new Error('No video url or mediaId in completed job. Head: ' + JSON.stringify(item).slice(0, 800));
return [{ json: { Video_Signed_URL: url || '', Video_Media_Id: mediaId || '' } }];

const sd = $getWorkflowStaticData('global');
sd.prevImageUrl = '';
sd.prevImageId = '';
sd.anchorId = '';
// Every per-scene counter in this workflow lives here and is reset per
// pass: video polls / resubmits (batch loop), regen polls / resubmits (the
// gate), multi-voice polls, motion-prompt rewrites, submit cooldowns.
// They are keyed by scene id because $runIndex counts a node's runs across
// the WHOLE execution — and a pass now covers the whole film.
sd.polls = {};
sd.resubmits = {};
sd.regenPolls = {};
sd.regenResubmits = {};
sd.multiPolls = {};
sd.rewrites = {};
sd.submitCooldowns = {};
sd.imgRewrites = {};
sd.imgCooldowns = {};
sd.consistencyRerolls = {};
sd.consistencyNotes = {};
sd.muxPolls = {};
// 2026-09-14 — the motion judge's two counters were missed when that feature
// went live the day before, so `MAX_REROLLS = 1` meant one re-roll per scene
// for the LIFE OF THE n8n PROCESS rather than one per pass: a scene that spent
// its re-roll on one film could never earn another. `consistencyRerolls` and
// `consistencyNotes` above are the still-image judge's exact analogues and have
// always been reset here; these two belong beside them, and the comment at the
// top of this block already claims that EVERY per-scene counter lives here.
//
// NOT wholesale, though, and that is the whole subtlety. This node runs on
// every REGEN cycle as well as every batch pass — `If Video Regen Pending` →
// `Fetch Approved Scenes` → `Warm-up Cooldown` → here — and `RG Motion Prep`
// keys the SAME object as 'regen:<scene id>'. Clearing it outright would reset
// the regen counter on every cycle and hand each regenerated scene an unlimited
// supply of re-rolls, a whole Veo generation apiece. So reset only the BATCH
// keys and leave the 'regen:' ones to the gate that owns them.
sd.motionRerolls = sd.motionRerolls || {};
sd.motionNotes = sd.motionNotes || {};
for (const k of Object.keys(sd.motionRerolls)) if (!k.startsWith('regen:')) delete sd.motionRerolls[k];
for (const k of Object.keys(sd.motionNotes)) if (!k.startsWith('regen:')) delete sd.motionNotes[k];
const items = $input.all().slice();
const ord = it => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
// "Done" is judged on the CLIP and the regen flags, never on the status
// text. It used to be the text ('Așteaptă Aprobare Video' / 'Finalizat'),
// and `VP Apply` stamped exactly that text on a scene whose clip had just
// been REFUSED by the video filter — so a refused scene sorted as finished,
// fell behind the cap on any film longer than 8 scenes, and was never
// generated again (Vegas, 71 scenes: 117, 118, 203 and 204 sat like that).
const pending = it => {
  const f = it.json.fields || {};
  const hasClip = String(f['Scene Final URL'] || '').startsWith('http');
  const flagged = f['Regenerează Video'] === true || f['Regenerează Imagine'] === true || f['Regenerează Voce'] === true;
  return !hasClip || flagged;
};
items.sort((a, b) => {
  const pa = pending(a), pb = pending(b);
  if (pa !== pb) return pa ? -1 : 1;
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
  return a.json.id < b.json.id ? -1 : 1;
});
if (!items.length) throw new Error('No approved scenes found for this project.');
// A pass covers the WHOLE film: every take, every image, one combined gate,
// every clip, one video gate. The cap was 8 until 2026-09-01, which turned a
// 71-scene film into nine rounds of approvals; the site mirrors this number
// in MEDIA_BATCH_CAP. 200 is a sanity bound (a 12-minute film is ~90
// scenes), not a chunk size. Pending-first sorting stays so a repeat pass
// (refused scenes, regen flags) still converges.
const CAP = 200;
if (items.length > CAP) {
  console.log('Sort & Cap: ' + items.length + ' approved scenes, running ' + CAP + '; ' + (items.length - CAP) + ' left for the next run.');
}
return items.slice(0, CAP);

const f = $json.fields || {};
const prompt = f['Imagine First Frame'] || f['Prompt Vizual'] || '';
if (!prompt) throw new Error('Scene ' + $json.id + ' has no image prompt.');
const rb = $('Receive Batch Input').first().json;
const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';
// Images are generated ON Google Flow (useapi POST /google-flow/images); the
// response carries the fifeUrl the ingest re-hosts and the mediaGenerationId
// Submit Video needs. One model string, here, in the gate's regen and in
// Claude Scripting's IR Build Request — the three must agree.
const MODEL = 'nano-banana-2';

// The project as read at pass start, plus whatever THIS pass stored after that
// read (the user photo id, the cast sheets, the set plates).
const projF = ($('IMG Load Project').first().json.fields || {});
let opts = {}; try { opts = JSON.parse(projF['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }
let bible = {}; try { bible = JSON.parse(projF['Story Bible'] || '{}') || {}; } catch (e) { bible = {}; }
try { if ($('Save User Ref Id').isExecuted) { const m = $('Save User Ref Id').first().json.media_id; if (m) opts.refImageMediaId = String(m); } } catch (e) {}
try { if ($('Save Cast Refs').isExecuted) { const j = $('Save Cast Refs').first().json; if (j.cast_refs) opts.castRefs = j.cast_refs; if (j.cast_sheets) opts.castSheets = j.cast_sheets; if (j.object_refs) opts.objectRefs = j.object_refs; } } catch (e) {}
try { if ($('Save Set Plates').isExecuted) { const j = $('Save Set Plates').first().json; if (j.location_refs) opts.locationRefs = j.location_refs; } } catch (e) {}
const userRefId = String(opts.refImageMediaId || '');
const isFirstScene = Number(f['Ordine Scenă']) === 1;

// n-1 chain: the previous scene's generated image, BY ITS FLOW MEDIA ID, read
// from the previous run of Decode Scene Image (run data survives Wait
// suspensions, unlike static data in test executions — execution 661).
let prevId = '';
let prevPrompt = '';
try {
  if ($runIndex > 0) {
    const prev = $('Decode Scene Image').all(0, $runIndex - 1);
    if (prev && prev[0] && prev[0].json && prev[0].json.mediaId) prevId = prev[0].json.mediaId;
    const prevReq = $('Build Image Request').all(0, $runIndex - 1);
    if (prevReq && prevReq[0] && prevReq[0].json) prevPrompt = prevReq[0].json.rawPrompt || '';
  }
} catch (e) { prevId = ''; }
// Similarity guard, unchanged: near-identical consecutive prompts keep the
// subject consistent by text alone; the reference would collapse the
// composition (the Porsche films). Sheets and plates are NOT subject to it —
// they carry identity and place, not layout.
const wordSet = (s) => new Set(String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(w => w.length > 3));
let promptSim = 0;
if (prevPrompt) {
  const A = wordSet(prompt), B = wordSet(prevPrompt);
  if (A.size && B.size) { let hit = 0; for (const w of A) if (B.has(w)) hit++; promptSim = hit / Math.max(A.size, B.size); }
}
if (promptSim > 0.55) prevId = '';
const afterRefusal = /AUTO-REWRITE/.test(String(f['Observații Scenă'] || ''));

// A consistency re-roll (Judge Verdict sent this scene back) tightens the
// wording and carries the judge's reasons; counted per scene per pass.
const sd = $getWorkflowStaticData('global');
sd.consistencyRerolls = sd.consistencyRerolls || {};
sd.consistencyNotes = sd.consistencyNotes || {};
const strict = (sd.consistencyRerolls[$json.id] || 0) > 0;
const strictNotes = strict ? String(sd.consistencyNotes[$json.id] || '') : '';
// ---------------------------------------------------------------------------
// REFERENCE ASSEMBLY — shared word for word by Build Image Request (batch),
// Evaluate Image Approval (the gate's regen) and IR Build Request (the site's
// regen). Change one, change all three: a re-rolled picture built from
// different references than its neighbours is the drift this exists to stop.
//
// Consistency comes from PICTURES the model is anchored to, never from prose:
//   - cast sheets   (castRefs / castSheets)   one per character, turnaround or portrait
//   - object sheets (objectRefs)              one per hero object (a car, a machine)
//   - set plates    (locationRefs)            one per bible location, wide, empty
//   - the producer's own photo                ground truth on scene 1
//   - the previous frame                      LAST, palette only
// Who and where come from the scene's own tags (`char:`, `obj:`, `loc:`),
// written by the segmenter; films made before the tags existed fall back to
// name matching on Prompt Vizual, exactly as the cast sheet did.
const CONS = (function () {
  const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const tagsOf = (f) => (Array.isArray(f['Tag-uri Scenă']) ? f['Tag-uri Scenă'] : []).map((t) => String(t));
  const tagged = (f, prefix) => tagsOf(f).filter((t) => t.startsWith(prefix)).map((t) => t.slice(prefix.length).trim()).filter(Boolean);
  const mentions = (text, name, allGivens) => {
    const full = norm(name);
    const given = norm(name.split(/\s+/)[0] || '');
    const keys = (allGivens || []).filter((g) => g && g === given).length > 1 ? [full] : [full, given];
    return keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(text));
  };
  // Which bible entries are IN this scene: tags first (exact names the
  // segmenter chose from the bible), name matching second.
  function present(f, entries, prefix, textFields) {
    const names = entries.map((e) => String((e || {}).name || '').trim()).filter(Boolean);
    const fromTags = tagged(f, prefix).map(norm);
    if (fromTags.length) return names.filter((n) => fromTags.includes(norm(n)));
    const text = ' ' + norm(textFields.map((k) => f[k] || '').join(' ')) + ' ';
    const givens = names.map((n) => norm(n.split(/\s+/)[0] || ''));
    return names.filter((n) => mentions(text, n, givens));
  }
  function plan(a) {
    // a: { f, opts, bible, prompt, prevId, userRefId, isFirstScene, afterRefusal, strict, strictNotes }
    const opts = a.opts || {}, bible = a.bible || {}, f = a.f || {};
    const castRefs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
    const castSheets = (opts.castSheets && typeof opts.castSheets === 'object') ? opts.castSheets : {};
    const objectRefs = (opts.objectRefs && typeof opts.objectRefs === 'object') ? opts.objectRefs : {};
    const locationRefs = (opts.locationRefs && typeof opts.locationRefs === 'object') ? opts.locationRefs : {};
    const chars = Array.isArray(bible.characters) ? bible.characters : [];
    const objs = Array.isArray(bible.objects) ? bible.objects : [];
    const locs = Array.isArray(bible.locations) ? bible.locations : [];
    const refs = []; // {id, role, name}
    const used = { cast: [], objects: [], location: '', user: false, palette: false };
    if (a.afterRefusal) {
      // A refusal is likeliest about a face; nothing is attached, the prompt
      // rewrite alone carries the retry. Same rule as before the sheets.
      return { refs, used, prompt: a.prompt };
    }
    const protagonist = (() => {
      const byRole = chars.find((c) => /protagonist|lead|main|hero/i.test(String((c || {}).role || '')));
      return String(((byRole || chars[0]) || {}).name || '');
    })();
    if (a.isFirstScene && a.userRefId) { refs.push({ id: a.userRefId, role: 'user', name: protagonist }); used.user = true; }
    // Cast: leads (turnaround sheets) first, then portraits; two at most —
    // a third sheet crowds the composition (measured on the cast sheet port).
    const inScene = present(f, chars, 'char:', ['Prompt Vizual']).filter((n) => castRefs[n]);
    inScene.sort((x, y) => ((castSheets[y] || {}).kind === 'turnaround') - ((castSheets[x] || {}).kind === 'turnaround'));
    for (const n of inScene) {
      if (used.user && norm(n) === norm(protagonist)) continue; // the photo is truer than the sheet
      if (used.cast.length >= 2) break;
      refs.push({ id: castRefs[n], role: 'cast', name: n }); used.cast.push(n);
    }
    const objsIn = present(f, objs, 'obj:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => objectRefs[n]);
    for (const n of objsIn) { if (used.objects.length >= 1) break; refs.push({ id: objectRefs[n], role: 'object', name: n }); used.objects.push(n); }
    const locIn = present(f, locs, 'loc:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => locationRefs[n]);
    if (locIn.length) { refs.push({ id: locationRefs[locIn[0]], role: 'place', name: locIn[0] }); used.location = locIn[0]; }
    // The previous frame, last, palette only — and only when there is room.
    if (a.prevId && refs.length < 5 && !refs.some((r) => r.id === a.prevId)) { refs.push({ id: a.prevId, role: 'palette', name: '' }); used.palette = true; }
    // The sentence names the references BY POSITION, so it is built from the
    // list rather than assumed.
    const parts = [];
    refs.forEach((r, i) => {
      const k = i + 1;
      if (r.role === 'user') parts.push('Reference image ' + k + ' is the producer\'s own photo and is GROUND TRUTH for that character: exactly the same face, hair, body and outfit.');
      else if (r.role === 'cast') parts.push('Reference image ' + k + ' is a character sheet of ' + r.name + ' shown from several angles: this character (a person, an animal or a creature, whatever the sheet shows) in the shot has EXACTLY that face or head, hair or markings, colours, build and wardrobe. Render ONE view of them inside the scene — never the sheet layout, never several copies, never the neutral backdrop.');
      else if (r.role === 'object') parts.push('Reference image ' + k + ' is a reference sheet of ' + r.name + ': the same object in the shot has exactly that design, colours, markings and materials — one instance, placed in the scene.');
      else if (r.role === 'place') parts.push('Reference image ' + k + ' is the PLACE (' + r.name + '): the same architecture, layout, landmarks, materials and the same arrangement of what stands where. Light, weather and time of day follow the text, not the plate; the plate is empty of people and its framing is not this shot\'s framing.');
      else if (r.role === 'palette') parts.push('The LAST reference image is only for colour palette and film look, never for layout and never for who or where anyone is.');
    });
    let prompt = a.prompt;
    if (parts.length) {
      prompt = parts.join(' ') + ' Compose the shot described here, which may place its subjects at any distance, angle or part of the location: ' + a.prompt;
      if (a.strict) prompt = 'STRICT MATCH — the previous attempt drifted from the references (' + String(a.strictNotes || 'identity or place did not match') + '). Wherever the text and the references disagree about how a person, object or place LOOKS, the references win. ' + prompt;
    }
    return { refs, used, prompt };
  }
  function apply(body, planned) {
    planned.refs.forEach((r, i) => { body['reference_' + (i + 1)] = r.id; });
    body.prompt = planned.prompt;
    return body;
  }
  return { norm, plan, apply, tagged };
})();
// ---------------------------------------------------------------------------
const planned = CONS.plan({ f: f, opts: opts, bible: bible, prompt: prompt, prevId: prevId, userRefId: userRefId, isFirstScene: isFirstScene, afterRefusal: afterRefusal, strict: strict, strictNotes: strictNotes });
// count: 1 is mandatory — the API DEFAULTS TO FOUR images. captchaRetry: 1
// because useapi's five captcha retries per request are pure spend while
// Google throttles the account; our own cooldown loop handles that.
const body = CONS.apply({ email: rb.Flow_Email || 'fermafabiz@gmail.com', model: MODEL, prompt: prompt, aspectRatio: aspect, count: 1, captchaRetry: 1 }, planned);
console.log('IMG refs for ' + $json.id + ': ' + (planned.refs.map((r) => r.role + (r.name ? '=' + r.name : '')).join(', ') || 'none') + (strict ? ' [STRICT]' : ''));
return [{ json: { sceneId: $json.id, requestBody: body, refs: planned.refs, used: planned.used, usedReference: planned.refs.length ? planned.refs[0].id : null, castUsed: planned.used.cast, userRefApplied: planned.used.user, strict: strict, rawPrompt: prompt, promptSimilarityToPrev: Number(promptSim.toFixed(2)) } }];

// Flow answers synchronously: media[0].image.generatedImage carries the
// signed fifeUrl (expires — Write Scene Image's ingest downloads it on the
// spot and re-hosts the bytes) and the mediaGenerationId that Submit Video
// uses as startImage. Same shape Extract Video URL reads for clips.
const resp = $json;
const m0 = ((resp.media || [])[0] || {});
const gi = (m0.image && m0.image.generatedImage) || {};
const url = gi.fifeUrl || '';
const mediaId = gi.mediaGenerationId || '';
if (!url || !mediaId) throw new Error('No image in Flow response. Head: ' + JSON.stringify(resp).slice(0, 400));
const sceneId = $('Build Image Request').first().json.sceneId;
return [{ json: { sceneId: sceneId, url: url, mediaId: mediaId } }];

// ---------------------------------------------------------------------------
// REFERENCE ASSEMBLY — shared word for word by Build Image Request (batch),
// Evaluate Image Approval (the gate's regen) and IR Build Request (the site's
// regen). Change one, change all three: a re-rolled picture built from
// different references than its neighbours is the drift this exists to stop.
//
// Consistency comes from PICTURES the model is anchored to, never from prose:
//   - cast sheets   (castRefs / castSheets)   one per character, turnaround or portrait
//   - object sheets (objectRefs)              one per hero object (a car, a machine)
//   - set plates    (locationRefs)            one per bible location, wide, empty
//   - the producer's own photo                ground truth on scene 1
//   - the previous frame                      LAST, palette only
// Who and where come from the scene's own tags (`char:`, `obj:`, `loc:`),
// written by the segmenter; films made before the tags existed fall back to
// name matching on Prompt Vizual, exactly as the cast sheet did.
const CONS = (function () {
  const norm = (s) => String(s ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const tagsOf = (f) => (Array.isArray(f['Tag-uri Scenă']) ? f['Tag-uri Scenă'] : []).map((t) => String(t));
  const tagged = (f, prefix) => tagsOf(f).filter((t) => t.startsWith(prefix)).map((t) => t.slice(prefix.length).trim()).filter(Boolean);
  const mentions = (text, name, allGivens) => {
    const full = norm(name);
    const given = norm(name.split(/\s+/)[0] || '');
    const keys = (allGivens || []).filter((g) => g && g === given).length > 1 ? [full] : [full, given];
    return keys.some((k) => k.length > 2 && new RegExp('\\b' + esc(k) + '\\b').test(text));
  };
  // Which bible entries are IN this scene: tags first (exact names the
  // segmenter chose from the bible), name matching second.
  function present(f, entries, prefix, textFields) {
    const names = entries.map((e) => String((e || {}).name || '').trim()).filter(Boolean);
    const fromTags = tagged(f, prefix).map(norm);
    if (fromTags.length) return names.filter((n) => fromTags.includes(norm(n)));
    const text = ' ' + norm(textFields.map((k) => f[k] || '').join(' ')) + ' ';
    const givens = names.map((n) => norm(n.split(/\s+/)[0] || ''));
    return names.filter((n) => mentions(text, n, givens));
  }
  function plan(a) {
    // a: { f, opts, bible, prompt, prevId, userRefId, isFirstScene, afterRefusal, strict, strictNotes }
    const opts = a.opts || {}, bible = a.bible || {}, f = a.f || {};
    const castRefs = (opts.castRefs && typeof opts.castRefs === 'object') ? opts.castRefs : {};
    const castSheets = (opts.castSheets && typeof opts.castSheets === 'object') ? opts.castSheets : {};
    const objectRefs = (opts.objectRefs && typeof opts.objectRefs === 'object') ? opts.objectRefs : {};
    const locationRefs = (opts.locationRefs && typeof opts.locationRefs === 'object') ? opts.locationRefs : {};
    const chars = Array.isArray(bible.characters) ? bible.characters : [];
    const objs = Array.isArray(bible.objects) ? bible.objects : [];
    const locs = Array.isArray(bible.locations) ? bible.locations : [];
    const refs = []; // {id, role, name}
    const used = { cast: [], objects: [], location: '', user: false, palette: false };
    if (a.afterRefusal) {
      // A refusal is likeliest about a face; nothing is attached, the prompt
      // rewrite alone carries the retry. Same rule as before the sheets.
      return { refs, used, prompt: a.prompt };
    }
    const protagonist = (() => {
      const byRole = chars.find((c) => /protagonist|lead|main|hero/i.test(String((c || {}).role || '')));
      return String(((byRole || chars[0]) || {}).name || '');
    })();
    if (a.isFirstScene && a.userRefId) { refs.push({ id: a.userRefId, role: 'user', name: protagonist }); used.user = true; }
    // Cast: leads (turnaround sheets) first, then portraits; two at most —
    // a third sheet crowds the composition (measured on the cast sheet port).
    const inScene = present(f, chars, 'char:', ['Prompt Vizual']).filter((n) => castRefs[n]);
    inScene.sort((x, y) => ((castSheets[y] || {}).kind === 'turnaround') - ((castSheets[x] || {}).kind === 'turnaround'));
    for (const n of inScene) {
      if (used.user && norm(n) === norm(protagonist)) continue; // the photo is truer than the sheet
      if (used.cast.length >= 2) break;
      refs.push({ id: castRefs[n], role: 'cast', name: n }); used.cast.push(n);
    }
    const objsIn = present(f, objs, 'obj:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => objectRefs[n]);
    for (const n of objsIn) { if (used.objects.length >= 1) break; refs.push({ id: objectRefs[n], role: 'object', name: n }); used.objects.push(n); }
    const locIn = present(f, locs, 'loc:', ['Prompt Vizual', 'Imagine First Frame']).filter((n) => locationRefs[n]);
