if (v.sheet_leak === true) bad.push('the reference sheet leaked into the frame');
const n = sd.consistencyRerolls[dec.sceneId] || 0;
const summary = 'identity=' + identity + ' wardrobe=' + wardrobe + ' place=' + place + (problems.length ? ' — ' + problems.join('; ') : '');
if (!bad.length) { console.log('JUDGE ok ' + dec.sceneId + ': ' + summary); return pass('ok'); }
if (n >= MAX_REROLLS) { console.log('JUDGE accepting ' + dec.sceneId + ' after ' + n + ' re-rolls with drift (' + bad.join(', ') + '): ' + summary); return pass('drift-accepted'); }
sd.consistencyRerolls[dec.sceneId] = n + 1;
sd.consistencyNotes[dec.sceneId] = (bad.join(', ') + (problems.length ? ': ' + problems.join('; ') : '')).slice(0, 400);
console.log('JUDGE re-roll ' + (n + 1) + '/' + MAX_REROLLS + ' for ' + dec.sceneId + ' (' + bad.join(', ') + '): ' + summary);
return [{ json: { sceneId: dec.sceneId, reroll: true, attempt: n + 1, problems: bad, discardedMediaId: dec.mediaId } }];

// The LAST frame of the shot, so direction stops being a matter of prose.
//
// OFF BY DEFAULT SINCE 2026-09-14. This chain runs only when a project's
// Editing Options says `"endFrame": true`. Read the gate block below before
// turning it on — the argument for opt-in is written there in full.
//
// useapi supports I2V-FL on every Veo variant, ours included: startImage plus
// endImage, "video ends with this frame" (end-frame-ONLY is not supported,
// which is why this chain is useless without `Image Media ID`). Given both,
// direction stops being rhetoric and becomes geometry.
//
// The end frame is drawn by the same image model that drew the first one,
// with the START frame as its reference, so composition, wardrobe, light and
// style carry over and only what moves has moved. It is scaffolding, not a
// deliverable: nobody reviews it, it is never stored on the scene, and if it
// fails the scene falls back to exactly the single-frame behaviour it has
// today. Images are free on the Ultra plan, so this costs queue time only.
//
// NOTE the mode exclusivity on the VIDEO call: reference_* and character_*
// trigger R2V on Veo and "cannot be combined with startImage / endImage".
const cs = $('Current Scene').first().json;
const f = cs.fields || {};
const rb = $('Receive Batch Input').first().json;

// THE GATE. Two independent ways this chain stays dark, and as of 2026-09-14
// the first of them is the DEFAULT.
//
// (1) OPT-IN: `opts.endFrame === true`, and nothing else, draws an end frame.
//
// SAY IT PLAINLY — THIS IS A REVERSAL OF A SAME-DAY CHANGE, NOT A CONSIDERED
// ROLLOUT. The end frame went live 2026-09-13 at 16:42, default ON, by the
// same author, and was never measured on a real film. CLAUDE.md's own
// open-work section says so in as many words: "None of that is a
// measurement." The only positive evidence that exists is one synthetic clip
// on a throwaway workflow (executions 12930 / 12947, scored direction 1,
// coherent 1, morph false) and those executions are gone with the workflows
// that made them — the record survives only as prose in
// `db/port/veo-direction/README.md`.
//
// Against that: the producer's VERY NEXT clip. The café film
// `recXibIyVuLvMIqy3` is the only real batch that has ever run with this
// chain switched on, and the first clip a human watched from it was rejected
// with seven faults — two of which are this feature's own signature:
//   - the stainless prep table vanishing at 5.25s and returning at 6.25s in a
//     slightly different place: a cross-dissolve between two INDEPENDENTLY
//     DRAWN keyframes whose camera position differs;
//   - "pleacă cu el apoi se întoarce nenatural" — the subject walking away
//     and turning back: an interpolator obeying a terminal constraint whose
//     end pose sits at or near the start pose. It must LAND on the frame it
//     is handed, so a round trip in the picture becomes a round trip in the
//     clip.
//
// THE MIDDLE ROAD WAS MEASURED BEFORE IT WAS REJECTED. The obvious answer —
// "draw the end frame only on the shots where it helps", i.e. a clear A-to-B
// path with ambiguous direction, skipping chained actions, held objects,
// returns and exits — was run against the 16 REAL repaired prompts of that
// film, which is what the pipeline writes from now on. It drew an end frame
// on 0 of 16. Its sub-rules alone: held object 16/16, two-or-more actions
// 15/16, names a camera move 14/16. Script and output in
// `db/port/motion-permanence/endframe/`. A heuristic that never fires is a
// global off switch wearing a heuristic's clothes, so it ships as an off
// switch instead of as a rule nobody can audit. (Its action counter was also
// miscounting: it matched the stillness clauses rule 6 now MANDATES — "the
// trays stay in her hands" — as if they were actions.)
//
// THE STRUCTURAL REASON OUTLIVES THAT HEURISTIC, and it is the part to
// remember: rule 6 (a) mandates a named camera move on EVERY SINGLE SHOT, and
// a moving camera guarantees that two independently drawn keyframes disagree
// about where the static set is. The end frame and rule 6 are not compatible
// for this pipeline's shot vocabulary. Anything that reconciles them has to
// change one of the two, not arbitrate between them shot by shot.
//
// OFF IS NOT A RETURN TO THE BROKEN STATE. ~18 films and 368 scenes were made
// before this chain existed, and the defect the producer complained about
// then — the car reversing into the yard — was diagnosed as the appended
// contradictory continuity clause and fixed at 16:29, twelve minutes BEFORE
// the end frame shipped. Turning this off therefore restores the behaviour
// that produced films the producer accepted, with that clause already gone.
// Direction survives without geometry in two places that need no second
// frame: rule 6 (b)'s hard "DIRECTION IS NOT OPTIONAL" clause with its worked
// counter-example, and `Motion Verdict`, which scores direction on the
// finished clip and re-rolls at a fresh seed below 0.5. `Motion Resubmit`
// already agrees with all of this in its own words — its remedy for a morph
// is to drop the end frame "which is exactly what the film did before end
// frames existed".
//
// It also buys back ~25-30s of queue time per scene (two image generations,
// two ~5.5s captchas) — 33-40 minutes a pass on an 80-scene film — and, on a
// hook scene, one fewer paid veo-3.1-fast generation risked for a frame
// nobody reviews.
//
// WHAT TURNS IT BACK ON: a measured A/B on one real film. The same scenes
// generated with and without an end frame, watched side by side. Not an
// argument — a comparison; this feature has already been shipped on an
// argument once. Nothing is deleted, both chains stay wired, and the trial
// costs one project setting.
//
// (2) sd.endFrameOffAt — a timestamp stamped by `Submit Cooldown Guard` the
// first time Flow rejects a submission carrying an end frame for a reason
// that names one. A TIMESTAMP rather than a boolean, and deliberately NOT
// reset by `Sort & Cap Scenes`: static data outlives the execution, so a flag
// set once would disable end frames for every future film until somebody
// noticed. This is a SEPARATE mechanism from (1) and is left exactly as it
// was — it is what protects a project that has deliberately opted in.
const OFF_FOR_MS = 6 * 60 * 60 * 1000;
const sd = $getWorkflowStaticData('global');
const offUntil = Number(sd.endFrameOffAt || 0) + OFF_FOR_MS;
const off = Date.now() < offUntil;
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }
const optedIn = opts.endFrame === true;
const wanted = optedIn && !off;

const startImage = f['Image Media ID'] || '';
// Strip the legacy "Negative:" tail before the image model sees it. Without
// this, nano-banana-2 is handed "no subtitles", "no lip movement" and
// "ambient/atmospheric motion only" as instructions for drawing a single
// still — and, worse, it is handed the tail of a chained action. Scene 3 of
// the café film ended "...and pivots back toward the swinging door", so the
// after-frame was drawn with the subject turned back toward the door, and the
// interpolator then had to LAND there: that is the producer's "walks away
// with it and turns back unnaturally", manufactured by our own end frame.
const motion = String(f['Video Scenă URL'] || '').split(/\s*Negative:\s*/i)[0].trim();
// 2026-09-14: `look` IS GONE, and the variable with it — it had no other
// reader in this node. It carried `Imagine First Frame` / `Prompt Vizual`,
// the scene's own image prompt, appended as "The shot was originally composed
// as: …". `reference_1` below already carries that composition
// pixel-for-pixel, so restating it in words only anchored the "after" onto
// the "before": the model was shown the first frame, told in prose what the
// first frame looks like, and asked for the last one. What comes back is a
// picture too close to the start frame — which leaves the interpolator eight
// seconds to fill and no distance to cover, and eight seconds of nothing to
// do is how a subject ends up performing one reach twice. The motion is the
// only thing that should describe the difference between the two frames.

// Both halves are required. Without the start frame there is nothing holding
// the composition steady, and without the motion there is no "after" to draw.
// Never return zero items — everything downstream is the rest of the batch.
if (!wanted || !startImage || !motion) {
  // The opt-in reason is reported FIRST when it applies: since 2026-09-14 it
  // is the reason nearly every skip has, and a log line blaming a Flow
  // rejection that never happened sends the next session hunting a phantom.
  // The opt-in test is strict `=== true` on purpose: the fail-safe direction is
  // OFF, so anything ambiguous stays off. But there is NO UI for this key —
  // `grep -rn endFrame platform/` is empty — so hand-edited JSON is the only way
  // in, and `"endFrame": "true"` (a string) is the likely first attempt. That
  // would be silently off while the JSON visibly says true, so the reason echoes
  // what was actually seen rather than asserting the key is absent.
  const seen = JSON.stringify(opts.endFrame);
  const why = !wanted ? (!optedIn ? 'end frames are opt-in since 2026-09-14 — Editing Options has endFrame=' + seen + ', needs the boolean true' : 'end frames paused until ' + new Date(offUntil).toISOString() + ' after a Flow rejection') : (!startImage ? 'no start frame' : 'no motion prompt');
  console.log('ENDFRAME ' + (f['Ordine Scenă'] ?? '?') + ': skipped, ' + why);
  return [{ json: { ok: false, sceneId: cs.id, reason: why } }];
}

const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';

// This asks for the END of the motion, not for a new shot. The wording leans
// hard on the reference for everything that must NOT change, because the
// failure mode of an end frame is not a wrong position — it is a
// different-looking scene, which would make Veo morph between two strangers
// instead of moving one.
//
// 2026-09-14: THE CAMERA-MOVE LICENCE IS GONE. The middle sentence used to
// end "…and whatever the camera move has brought into or out of view", which
// is precisely the clause that licensed the two keyframes to disagree about
// where the static set is — and because rule 6 (a) mandates a camera move on
// every shot, that licence applied to every shot in every film. The
// producer's prep table popping out of frame at 5.25s and back at 6.25s in a
// different place IS that clause, rendered. The set is now pinned: only the
// moving subject may differ, the fixtures and the frame do not.
//
// BE HONEST ABOUT WHAT THAT TRADE IS, because "the frame stays exactly where
// the reference put it" pins the CAMERA, not only the set. So on an opted-in
// shot the end frame now depicts a camera that never moved, while the motion
// string handed to Veo still opens with a mandated named move — 14 of the 16
// measured prompts name one. The two no longer agree, and that is a CHOICE:
// given a pipeline where every shot names a camera move, a keyframe pair that
// disagrees about the set is a guaranteed artefact, whereas a terminal frame
// that under-describes the camera is a hint the model can overrule. We would
// rather lose the camera's contribution to the end frame than keep licensing
// the set to move. It is also the reason this feature is opt-in from today
// rather than tuned: with a camera move on every shot there is no wording
// that makes an end frame safe here, only wordings that make it less bad.
const prompt = [
  'This is the FINAL FRAME of a single continuous shot: the same camera, the same subject and the same place as the reference image, a few seconds later, after the following motion has fully completed:',
  motion,
  'Draw the world exactly as the reference image shows it — same characters, same faces, same wardrobe, same vehicles and objects, same setting, same lighting and time of day, same lens and framing style. The ONLY thing that may differ is where the moving subjects have got to: every fixed part of the set — walls, furniture, fittings, doors, signage, parked vehicles, anything nobody touches — stays in exactly the position, size and angle the reference shows it in, and the frame stays exactly where the reference put it. Do not restage the shot, do not change the angle for effect, do not add or remove anyone, and do not put any text on the image.',
].filter(Boolean).join(' ');

// count: 1 is mandatory — this endpoint DEFAULTS TO FOUR images. captchaRetry
// 1 because useapi's five captcha retries are pure spend while Google
// throttles.
const body = {
  email: rb.Flow_Email || 'fermafabiz@gmail.com',
  model: 'nano-banana-2',
  prompt: prompt,
  aspectRatio: aspect,
  count: 1,
  captchaRetry: 1,
  reference_1: startImage,
};

console.log('ENDFRAME ' + (f['Ordine Scenă'] ?? '?') + ': drawing the after-frame from ' + startImage);
return [{ json: { ok: true, sceneId: cs.id, requestBody: body } }];

// Read the end frame out of the Flow response — and never, ever throw.
//
// This node is scaffolding on the happy path of the whole batch. If it fails
// the scene must still get its clip the way it did before end frames existed,
// so every failure here returns an EMPTY endImage rather than an error:
// `Generate End Frame` carries onError: continueRegularOutput for the same
// reason, which means $json may well be an error envelope rather than a Flow
// response.
//
// Same response shape `Decode Scene Image` reads:
//   media[0].image.generatedImage.{ fifeUrl, mediaGenerationId }
// Only the id matters here — the picture is never stored, re-hosted or shown.
const efp = (() => { try { return $('End Frame Prompt').first().json || {}; } catch (e) { return {}; } })();
const sceneId = efp.sceneId || '';

let endImage = '';
let why = '';
try {
  const resp = $json || {};
  if (resp.error) {
    why = String(resp.error.message || resp.error.description || resp.error).slice(0, 200);
  } else {
    const gi = (((resp.media || [])[0] || {}).image || {}).generatedImage || {};
    endImage = gi.mediaGenerationId || '';
    if (!endImage) why = 'no mediaGenerationId in response: ' + JSON.stringify(resp).slice(0, 200);
  }
} catch (e) {
  why = 'unreadable response: ' + String(e && e.message || e).slice(0, 200);
}

// sceneId travels with it because `Submit Video` is reached by four edges and
// reads this node with .first(), which returns a node's LATEST run rather than
// the run belonging to the item in hand. On a scene that skipped the end frame
// that latest run is the PREVIOUS scene's — so Submit Video attaches the id
// only when the scene ids match, and this is the half that makes that possible.
if (endImage) console.log('ENDFRAME ' + sceneId + ': got ' + endImage);
else console.log('ENDFRAME ' + sceneId + ': none, falling back to start frame only — ' + why);

return [{ json: { sceneId: sceneId, endImage: endImage, reason: why } }];

// Decide whether this clip's MOTION is worth measuring, and write the
// question if it is.
//
// The pipeline's hardest-won rule, already written into `Judge Prep` one
// stage upstream: an instruction in a prompt is not a constraint. Every
// change in this feature — the direction clause, the end frame — asks Veo
// more nicely. Nothing yet LOOKS at what came back. So the clip gets the
// same treatment the still already gets: a contact sheet, a vision model,
// and a score rather than a hope.
//
// This is the node that says no. Judging every clip of an eighty-scene film
// costs a Railway download plus a gpt-4o call each, and a re-roll costs a
// whole Veo generation, so the gates are deliberate:
//   - motionJudge: false in Editing Options turns it off entirely;
//   - a scene already re-rolled MAX_REROLLS times is not judged again —
//     there is nothing left to do with the answer;
//   - a clip with no signed URL cannot be inspected (Extract Video URL
//     sometimes recovers only a media id);
//   - a scene with no motion prompt has no claim to check the clip against.
// Never return zero items: the rest of the batch is downstream.
const ev = $json; // Extract Video URL: {Video_Signed_URL, Video_Media_Id}
const cs = $('Current Scene').first().json;
const f = cs.fields || {};
const sd = $getWorkflowStaticData('global');
sd.motionRerolls = sd.motionRerolls || {};

const MAX_REROLLS = 1;
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }

// Strip the legacy "Negative:" tail before the judge sees it, the same way
// `Current Scene`, `Submit Video Regen` and `End Frame Prompt` now do. The
// stored prompt on every scene written before 2026-09-13 ends in ~355
// characters of prohibitions, and this node hands the whole thing to the
// vision model as THE BRIEF — so the judge was being asked whether the clip
// matches a list of things that must not happen. It scored the shot against
// "no oncoming vehicles" and "no reversed motion" as if those were the
// director's intent. New scenes store the action only and this line is a
// no-op for them; it exists for the 368 rows that do not.
const motion = String(f['Video Scenă URL'] || '').split(/\s*Negative:\s*/i)[0].trim();
const done = (sd.motionRerolls[cs.id] || 0) >= MAX_REROLLS;
const skip = opts.motionJudge === false ? 'motionJudge: false'
  : (!ev.Video_Signed_URL ? 'no signed clip URL to inspect'
  : (!motion ? 'no motion prompt to judge against'
  : (done ? 'already re-rolled ' + MAX_REROLLS + ' time(s)' : '')));

const base = { sceneId: cs.id, ord: f['Ordine Scenă'], videoUrl: ev.Video_Signed_URL || '', mediaId: ev.Video_Media_Id || '', passthrough: ev };
if (skip) {
  console.log('MOTION ' + (f['Ordine Scenă'] ?? '?') + ': not judged, ' + skip);
  return [{ json: Object.assign({}, base, { ok: false, reason: skip }) }];
}

// The sheet is frames in time order, so the question is asked in those
// terms. SIX things are checked and they fail differently — the first three
// were here from the start, the last three were added on 2026-09-13 after a
// café clip failed in three ways this judge could not see:
//
//   direction — the originally reported bug. The scene said the car leaves
//     the yard and the clip had it reversing in. Note the wording asks only
//     about what the SENTENCE claims, not about whether the shot is good: a
//     judge given licence to have taste will re-roll half the film.
//   morph — the risk the end frame introduced. Given two frames Google
//     routes this tier to veo_3_1_interpolation_lite_low_priority, and an
//     interpolator handed two frames that differ too much dissolves between
//     them instead of moving anything. That failure is invisible to a
//     direction question: the car does end up outside the gate, by fading
//     there. It is also the one failure whose fix is NOT another roll of the
//     dice — see `Motion Resubmit`.
//   coherent — the catch-all the producer described as "lucruri fără
//     logică": things sliding through each other, a vehicle with no driver.
//     NARROWED when permanence arrived: things appearing and disappearing
//     used to be listed here too, and asking two questions about the same
//     failure only splits the signal.
//
//   permanence — "personajul ia ceva in mana apoi dispare". A held object
//     leaving the hands, a prep table vanishing and coming back in a
//     different place, an apron changing cut between frames, a subject
//     duplicating. A presence question, which a contact sheet reads more
//     reliably than anything else here.
//   untouched — "usa la frigider se deschide singura", "bate vantul peste
//     acele foi lipite". A door or drawer moving with no hand on it, paper
//     or cloth stirring indoors where there is no wind. This is the score
//     most exposed to false positives, because plenty of real motion has a
//     cause outside the frame — hence the lowest threshold in `Motion
//     Verdict`.
//   loop — "pleaca cu el apoi se intoarce nenatural". The signature of a
//     brief with more actions in it than fit in eight seconds: the model
//     performs the first one twice, or walks out and comes back, to fill the
//     time. Rule 6 now forbids writing such a brief, but the 368 scenes
//     already in Postgres still carry them.
//
// BOTH NEW QUESTIONS CARRY AN EXPLICIT CARVE-OUT, for the same reason
// `direction` has one ("if the brief names no direction, answer 1"). Rule 6
// MANDATES a named camera move on every shot, so things entering and leaving
// frame is the design rather than an edge case, and an absolute permanence
// question would dock well-made pans. And `untouched` is a rule about
// INTERIORS: outdoors, wind, water, foliage, traffic and crowds move with
// nobody touching them and that is correct. A question with no carve-out
// would re-roll street scenes for being streets.
const system = 'You are a film editor checking whether a generated shot does what its brief said. You are shown a contact sheet: frames sampled at a fixed interval across a single 8-second clip, in time order, left to right and then top to bottom. The frames are samples, not the whole clip: a fault shorter than the gap between two of them is invisible here, so judge what you can actually see and do not infer what happened in between. Judge only what the brief claims and whether the world holds together. Do not judge taste, style, beauty, lighting or composition. Answer only the JSON object requested.';
const ask = [
  'The brief for this shot was:',
  '"' + motion.slice(0, 700) + '"',
  'Score each 0 to 1.',
  '"direction": does the movement across the frames match what the brief says, including which way things travel and whether they approach or leave? 1 = it does what the brief says; 0 = it does the opposite (the brief says out and the subject goes in, or the brief says left to right and it goes right to left). If the brief names no direction, answer 1.',
  '"permanence": does everything keep its identity and stay present from the first frame to the last? Lower it when something a character is holding disappears from their hands, when a prop or a piece of furniture vanishes and later comes back, when clothing changes between frames, or when a person or object duplicates. Judge only what the frames can actually show: a thing that leaves the frame because the CAMERA moved, or passes behind something else, has not vanished, and every shot here has a camera move. If you simply cannot follow an object, answer 1 rather than guess. 1 = nothing that should still be visible appears or disappears.',
  '"untouched": does everything that cannot move by itself hold still? Lower it when a door, a drawer, a lid or a window opens or closes with no hand on it, when paper, cloth, curtains or hanging signs move INDOORS where there is no wind, or when an object slides with nothing pushing it. This question is about interiors and about objects with no motive power of their own: outdoors, wind, weather, water, foliage, traffic, animals and crowds move on their own and that is correct, so answer 1 for an exterior unless a door, a lid, a drawer or a piece of furniture moves with nobody near it. 1 = nothing moved that had no cause.',
  '"coherent": does the sequence hold together physically? Lower it when solid things pass through each other, when something floats or sinks into the ground, or when a moving vehicle has no driver.',
  '"morph": true if the frames do not show real movement but a dissolve or warp between two different pictures — the subject changing shape, sliding without turning its wheels or legs, or the scene cross-fading. Otherwise false.',
  '"loop": true if the clip fills its eight seconds by repeating or doubling back — the subject performs the same action twice, or walks out of frame and returns to where it started, or the camera travels somewhere and comes back. Otherwise false.',
  'Answer ONLY JSON: {"direction": number, "permanence": number, "untouched": number, "coherent": number, "morph": boolean, "loop": boolean, "problems": ["short concrete reason", ...]}',
].join(' ');

console.log('MOTION ' + (f['Ordine Scenă'] ?? '?') + ': judging');
return [{ json: Object.assign({}, base, { ok: true, system: system, ask: ask, motion: motion }) }];

// Read the judge's answer and decide: keep the clip, or spend one more
// generation on it.
//
// Shaped exactly like `Judge Verdict` one stage upstream, and for the same
// reason: bounded per scene per pass, and every way of not getting an answer
// (skipped, unreadable, the HTTP call failed) means KEEP. A judge that can
// take a film down by being unavailable is worse than no judge.
//
// 2026-09-13 (evening) — two new failure modes, `permanence` and `untouched`,
// plus the `loop` boolean. `Motion Prep` now asks the vision model for six
// signals instead of four; this node had to learn to read them or the extra
// questions would have been asked and thrown away. What each one is, and why
// it exists, is in ../README.md — the café clip where the producer counted a
// held object vanishing, the same reach performed twice, papers flapping
// indoors, a fridge door and a room door moving by themselves, a prep table
// popping out and back, and the subject walking away and turning back. The
// prompt fixes (rule 6, `Current Scene`, `Submit Video Regen`) ask Veo not to
// do those things. This node is the half that CHECKS.
//
// AN OLD ANSWER MUST STILL BE SAFE. If a judge reply arrives without the new
// fields — a rolled-back `Motion Prep`, a model that drops a key, a truncated
// completion — `num()` returns null and the boolean is not `true`, so those
// gates simply do not fire and the clip is kept. Absence is never a failure.
const prep = $('Motion Prep').first().json;
const sd = $getWorkflowStaticData('global');
sd.motionRerolls = sd.motionRerolls || {};
sd.motionNotes = sd.motionNotes || {};
const MAX_REROLLS = 1;

// What flows on is the ORIGINAL Extract Video URL item, untouched — this
// node sits in the middle of the download/upload chain and everything after
// it reads Video_Signed_URL / Video_Media_Id.
const keep = (why) => [{ json: Object.assign({}, prep.passthrough || {}, { motionVerdict: why, motionReroll: false }) }];

if (!prep.ok) return keep(prep.reason || 'not judged');

let v = null;
try {
  const text = (($json.choices || [])[0] || {}).message ? String((($json.choices || [])[0] || {}).message.content || '') : '';
  const m = text.match(/\{[\s\S]*\}/);
  v = m ? JSON.parse(m[0]) : null;
} catch (e) { v = null; }
if (!v) {
  console.log('MOTION ' + prep.ord + ': unreadable judge answer, keeping — ' + JSON.stringify($json).slice(0, 200));
  return keep('unreadable');
}

const num = (x) => (typeof x === 'number' && isFinite(x)) ? x : null;
const direction = num(v.direction);
const permanence = num(v.permanence);
const untouched = num(v.untouched);
const coherent = num(v.coherent);
const morph = v.morph === true;
const loop = v.loop === true;
const problems = Array.isArray(v.problems) ? v.problems.map(String).slice(0, 4) : [];

// The thresholds are low ON PURPOSE. A re-roll costs a whole Veo generation
// and a place in the queue, so this only fires when the judge is confident
// the shot contradicts its brief — not when it is merely unenthusiastic.
//
// Why the two new numbers sit where they do:
//
//   permanence 0.5 — the same bar as direction, and deliberately NOT softer
//     than coherence. This is the failure the producer actually reported, and
//     it is also the one a contact sheet reads most reliably: "the stack is in
//     her hand at t=2 and gone at t=3" is a presence question, not a question
//     of taste. It still cannot be set higher: on a sheet sampled a second
//     apart, an object can leave frame because the camera panned, or a person
//     can pass behind a counter, and an honest judge docks a little for
//     anything it loses track of. 0.5 is the point where the model is saying
//     "more vanished than not" rather than "I could not follow it". The
//     question in `Motion Prep` now says so explicitly — a thing that leaves
//     frame because the CAMERA moved has not vanished, and an object it
//     cannot follow scores 1 rather than a guess — because EVERY shot this
//     pipeline writes has a named camera move (rule 6 mandates one), so
//     things entering and leaving frame is the design, not an edge case.
//     Without that carve-out this gate would fire on well-made pans.
//
//   untouched 0.45 — the floor, level with coherence, because this is the
//     score most exposed to FALSE POSITIVES. Plenty of legitimate motion has
//     a cause that is invisible in frame: a door someone opened just off
//     camera, a curtain at an open window, steam, traffic, a crowd, anything
//     outdoors where wind is real. The rule the prompt teaches is about indoor
//     stillness, but the judge is scoring exteriors with the same question, so
//     it will dock them. Setting this any higher would re-roll street scenes
//     for being streets. The question itself now carves exteriors out — wind,
//     weather, water, foliage, traffic, animals and crowds move on their own
//     and score 1 — so the threshold is the second line of defence, not the
//     first. If this gate still fires on ordinary outdoor films, the wording
//     is what to fix, not the number.
//
//   loop — a boolean like morph, and treated like one: no threshold to argue
//     about, it either doubled back or it did not. It is the direct signature
//     of the three-chained-actions bug from the README (the model has more to
//     do than fits in eight seconds, so it performs the first action twice, or
//     walks out and returns). Rule 6 now forbids writing such a brief, but
//     briefs already in Postgres still carry them, and a re-roll at a new seed
//     genuinely does sometimes pace it differently.
//
// SIX SIGNALS FIRING ONE SHARED RE-ROLL IS THE REAL RISK HERE, not any single
// number. Each gate is individually conservative, but they compound: if every
// one of them is wrong about one clip in ten, better than a third of a film
// gets re-rolled. MAX_REROLLS = 1 still caps the SPEND at one extra
// generation per scene — what grows is how often that ceiling is reached. A
// combination rule (three mild dips add up to a re-roll even though no gate
// fires) was considered and deliberately left out: it is exactly how a judge
// starts re-rolling half a film, and there is no fire-rate measurement yet to
// justify it. The measurement comes first — which is why the summary below
// prints all six on EVERY path, kept clips included, so one `grep 'MOTION '`
// over a real film's execution log gives the per-signal rates without
// re-running anything. That is the open-work item in CLAUDE.md ("watch one
// real film and count how many clips the judge re-rolls"), and these two new
// numbers are now part of what it has to count.
const bad = [];
if (direction !== null && direction < 0.5) bad.push('direction ' + direction);
if (permanence !== null && permanence < 0.5) bad.push('permanence ' + permanence);
if (untouched !== null && untouched < 0.45) bad.push('untouched ' + untouched);
if (coherent !== null && coherent < 0.45) bad.push('coherence ' + coherent);
if (morph) bad.push('morph');
if (loop) bad.push('loop');

const summary = 'direction=' + direction + ' permanence=' + permanence + ' untouched=' + untouched + ' coherent=' + coherent + ' morph=' + morph + ' loop=' + loop + (problems.length ? ' — ' + problems.join('; ') : '');
const n = sd.motionRerolls[prep.sceneId] || 0;
if (!bad.length) { console.log('MOTION ' + prep.ord + ': ok, ' + summary); return keep('ok'); }
if (n >= MAX_REROLLS) { console.log('MOTION ' + prep.ord + ': still wrong after ' + n + ' re-roll(s), keeping it (' + bad.join(', ') + '): ' + summary); return keep('wrong-accepted'); }

sd.motionRerolls[prep.sceneId] = n + 1;
sd.motionNotes[prep.sceneId] = (bad.join(', ') + (problems.length ? ': ' + problems.join('; ') : '')).slice(0, 400);
console.log('MOTION ' + prep.ord + ': re-roll ' + (n + 1) + '/' + MAX_REROLLS + ' (' + bad.join(', ') + '): ' + summary);
// `morph` stays the key `Motion Resubmit` reads to drop the end frame — that
// contract is unchanged. `loop` rides along beside it but does NOT drop the
// end frame today, and the omission is on purpose rather than an oversight: a
// loop CAN share morph's root cause (an end frame so close to the start that
// the only way to reach it is to go somewhere and come back), in which case a
// new seed will not help either — but it is just as often the three-actions
// brief, where the end frame is the thing holding the shot together and
// throwing it away would make the clip worse. Wiring loop into dropEndFrame
// is a change to `Motion Resubmit`, to be made when a real film has shown
// which of the two causes is the common one. Passing the flag now means that
// change is one line there and none here.
return [{ json: { sceneId: prep.sceneId, ord: prep.ord, motionReroll: true, morph: morph, loop: loop, attempt: n + 1, problems: bad, discardedMediaId: prep.mediaId } }];

// Send the scene back to Submit Video for one more take — differently.
//
// A plain resubmit would be pointless. `Current Scene` derives the seed from
// the scene id and the number of takes already FILED, and a take rejected
// here is never filed, so the second submission would carry the same seed,
// the same prompt and the same frames — and Veo would return the same clip.
// (The existing `Resubmit Guard` has the same blind spot, harmlessly: it
// retries jobs that FAILED, where an identical request is the right thing.)
// So this node hands Submit Video three overrides, and the expression there
// applies them only when the scene ids match.
const v = $json; // Motion Verdict, reroll branch
const sd = $getWorkflowStaticData('global');

// Polls are counted per scene and the previous take already spent some of
// them; without this the new job could be declared timed out on arrival.
// `Resubmit Guard` does exactly the same for the same reason.
sd.polls = sd.polls || {};
sd.polls[v.sceneId] = 0;

const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const seed = hash(String(v.sceneId) + ':motion:' + v.attempt) % 2147483647;

// MORPH IS THE ONE VERDICT A DIFFERENT SEED CANNOT FIX. It means the two
// frames were too far apart for the interpolator, so it dissolved between
// them instead of moving anything — and the same two frames will dissolve
// again at any seed. The right answer is to give up the end frame for this
// scene and let Veo animate freely from the still, which is exactly what the
// film did before end frames existed.
const dropEndFrame = v.morph === true;

// 2026-09-14 — THE RE-ROLL NOW CARRIES WHAT THE JUDGE FOUND.
//
// Until today a re-roll was A NEW SEED AGAINST A BYTE-IDENTICAL BRIEF. The
// judge scored six signals and `Motion Verdict` filed its prose under
// `sd.motionNotes` — a key nothing in either workflow has ever read. So a
// clip rejected because a held object left the subject's hands was sent
// back with exactly the sentence that produced it, and the only thing
// between us and the same clip was the dice.
//
// WHY THE JUDGE'S OWN WORDS CANNOT BE THE CORRECTION. `problems` is written
// as FAULTS — "the sleeve stack disappears from her hands". Pasting that
// into a Veo prompt is precisely the bug the whole of 2026-09-13 was spent
// removing: Google's guidance is that naming an unwanted thing makes the
// model render it, and our own tail saying "nothing appears, disappears or
// duplicates" is what produced a disappearing object. See ../README.md and
// docs/lessons-pipeline.md, "A prompt that names a failure summons it". A
// correction quoting the fault would walk the anti-pattern straight back in
// through the one door that was just closed, on the one path where nobody
// would see it until a producer watched the film.
//
// TWO SHAPES WERE CONSIDERED; THIS IS (a), THE DETERMINISTIC ONE.
//   (b) a second model call that rewrites each fault into a positive
//       requirement. More faithful to the specific fault — and it puts a
//       generative step between the judge and Veo precisely where a leaked
//       negation is invisible, adds a call that can time out inside what is
//       already a retry, and spends latency saying something the fault
//       CATEGORY already implies.
//   (a) a fixed map from SIGNAL to positive clause. Chosen. The signals are
//       a closed set of six, written by `Motion Verdict` two nodes upstream,
//       and each one names a failure MODE rather than an incident:
//       "permanence" is always "something stopped being there", whatever the
//       thing was. So the clause can be authored once, by hand, in the same
//       positive world-state voice as WORLD_RULES — and being a literal it
//       CANNOT smuggle a negation, which is the single property that matters
//       here. What it gives up is specificity: the re-roll is told "whatever
//       the subject is holding stays in their hands" rather than "the sleeve
//       stack stays in her hands". That costs little, because Veo is handed
//       the start frame and the thing is in front of it.
//
// EVERY CLAUSE IS A POSITIVE WORLD-STATE. Read them as a set: not one of
// them names the failure it repairs, and none of them contains "no", "not"
// or a fault noun. `UNSAFE` below enforces that at runtime rather than
// leaving it as a promise in a comment, because the next session to add a
// seventh signal will be editing a plain object literal and will not
// necessarily have read this paragraph.
//
// THIS MAP IS A LOCKSTEP PAIR WITH `RG Motion Resubmit`. The two nodes hold
// byte-identical copies of CLAUSES, SIGNAL_ORDER, MAX_CLAUSES, LEAD_IN and
// UNSAFE — the producer's regeneration must be corrected the same way the
// batch is, or a rescued clip obeys a different director from its
// neighbours. Change both or neither. n8n has no shared module; the
// duplication is the price.
const CLAUSES = {
  permanence: 'Whatever the subject is holding stays in their hands for the whole shot and is there in the final frame; every prop, garment and piece of furniture keeps the shape, colour and cut it has in the opening frame.',
  untouched: 'Every door, drawer, lid, window and taped-up sheet of paper stays exactly as the opening frame shows it, and moves only in the instant a hand moves it; indoors the air is still.',
  loop: 'One single continuous action, performed once and carried straight through to the final frame; the subject ends the take somewhere new, further along than it began.',
  direction: 'Everything that travels keeps the one direction the action above names and holds that heading to the final frame; the camera keeps the move it was given and travels that way throughout.',
  coherence: 'Solid things keep their own space: feet stay on the ground, people and vehicles pass around each other, and every vehicle that moves has a driver at its controls.',
  morph: 'Everything that changes on screen changes because something physically moves — wheels turn, legs step, hands travel — and every shape keeps its own edges for the whole take.',
};

// Priority, and it only bites when more than MAX_CLAUSES fire at once. The
// three the producer actually reported come first (a held object gone, a
// door opening by itself, the eight seconds filled by doing one thing
// twice); `morph` is last because its real remedy is dropping the end frame
// above, and its clause is only there so a morph re-roll is not sent back
// with nothing said at all.
const SIGNAL_ORDER = ['permanence', 'untouched', 'loop', 'direction', 'coherence', 'morph'];

// THE CAP IS THE KNOB TO TURN IF RE-ROLLS COME BACK WORSE. Three clauses is
// ~100 words on top of a prompt that is already ~180, and attention is
// finite: past some length the correction dilutes the action it is meant to
// protect. Three is the café clip's own count (permanence, untouched, loop),
// so it is the smallest cap that would have carried that whole diagnosis.
const MAX_CLAUSES = 3;
const LEAD_IN = 'CORRECTION — the new take MUST hold to this: ';

// The executable half of "every clause is positive". A clause matching this
// is withheld and logged rather than sent: a negation reaching Veo is the
// failure this entire feature exists to avoid, and a re-roll that carries
// one clause fewer is merely today's behaviour for that signal.
const UNSAFE = /\b(?:no|not|never|none|nothing|nobody|nor|without|avoid\w*|prevent\w*|stop\w*|remove\w*|don't|doesn't|isn't|aren't|disappear\w*|vanish\w*|duplicat\w*|morph\w*|warp\w*|flicker\w*)\b/i;

// WHICH SIGNALS FIRED. `Motion Verdict` sends `problems` as the GATE list
// ("permanence 0.3", "untouched 0.4", "morph", "loop") — NOT the judge's
// prose, which never leaves `sd.motionNotes`. The key names lie about that,
// so read the first word and nothing else. `morph`/`loop` are re-checked off
// their own booleans so an older or partial verdict payload still corrects
// what it can; an unrecognised entry is simply ignored, exactly as a missing
// score is ignored one node upstream.
const fired = [];
const seen = (Array.isArray(v.problems) ? v.problems : []).map((p) => String(p).trim().split(/\s+/)[0].toLowerCase());
if (v.morph === true) seen.push('morph');
if (v.loop === true) seen.push('loop');
seen.forEach((k) => { if (CLAUSES[k] && fired.indexOf(k) < 0) fired.push(k); });

const withheld = fired.filter((k) => UNSAFE.test(CLAUSES[k]));
if (withheld.length) console.log('MOTION ' + v.ord + ': clause withheld, a negation reached the map — ' + withheld.join(', '));
const used = SIGNAL_ORDER.filter((k) => fired.indexOf(k) >= 0 && withheld.indexOf(k) < 0).slice(0, MAX_CLAUSES);
const correction = used.length ? LEAD_IN + used.map((k) => CLAUSES[k]).join(' ') : '';

// WHERE THE CORRECTION LANDS, and why it is not simply appended.
//
// `Current Scene` froze this scene's prompt as SHOT_RULES + action +
// WORLD_RULES, and WORLD_RULES ends with the trailing `Negative:` NOUN LIST.
// Appending would put the correction inside that list — the same mistake
// `Evaluate Video Approval` made with the producer's own adjustment note,
// where a human typing "she should keep holding the stack" was handing Veo
// one more thing to avoid. So the insert is at the first `Negative:`
// boundary, with everything from that token onward preserved byte for byte.
// This is the canonical split five nodes already use, read as an index
// instead of a split so the tail survives untouched.
//
// It sits after WORLD_RULES rather than beside the action deliberately: the
// boundary between the action and WORLD_RULES is only findable by matching
// `Current Scene`'s literal wording, which would be a silent coupling to a
// string that changes. `Negative:` is a token every composer in this
// workflow already agrees on.
//
// `Submit Video` copies `cs.videoRequest` WHOLESALE and has never read a
// prompt from anywhere else, so the one-line override there is what makes
// this reach Veo at all. Without that edit this node is a no-op: the seed
// and the end-frame drop still work, the correction is composed and logged
// and thrown away.
//
// `basePrompt` is the staleness guard. `Current Scene` can run a SECOND time
// for the same scene id — `VP Reload Scene` re-enters it after the video
// filter refuses a prompt and `VP Apply` rewrites it — and `Submit Video`
// reads this node with `.first()`, which returns its LATEST run rather than
// the run belonging to the item in hand. Matching on the scene id alone
// would then resurrect a correction built on the REFUSED prompt and undo the
// rewrite that exists to get past the filter. Matching the base string means
// the override applies only to the exact prompt it was derived from.
let basePrompt = '';
let prompt = '';
if (correction) {
  try { basePrompt = String((($('Current Scene').first().json || {}).videoRequest || {}).prompt || ''); } catch (e) { basePrompt = ''; }
  const cut = basePrompt ? basePrompt.search(/\s*Negative\s*:/i) : -1;
  const head = (cut >= 0 ? basePrompt.slice(0, cut) : basePrompt).trim();
  const tail = cut >= 0 ? basePrompt.slice(cut) : '';
  // A head of nothing means the stored prompt was a bare legacy tail (the
  // rare row `Evaluate Video Approval` also guards against). Correcting an
  // empty action would send Veo the correction and no shot at all, so that
  // one case falls back to today's behaviour: new seed, prompt untouched.
  if (head) prompt = head + ' ' + correction + tail;
}

console.log('MOTION ' + v.ord + ': resubmitting with seed ' + seed + (dropEndFrame ? ', WITHOUT the end frame (morph)' : ''));
// Printed on EVERY re-roll, empty correction included, for the same reason
// `Motion Verdict` prints all six signals on every path: the open-work item
// in CLAUDE.md is to watch one real film and count, and `grep 'MOTION '` over
// one execution log has to answer "did the correction ride along, and which
// clauses" without re-running anything.
console.log('MOTION ' + v.ord + ': correction ' + (used.length ? '(' + used.join(', ') + ')' : '(none)') + (prompt ? ', ' + prompt.length + ' chars' : ', prompt unchanged'));
return [{ json: { sceneId: v.sceneId, ord: v.ord, seed: seed, dropEndFrame: dropEndFrame, attempt: v.attempt, correction: correction, basePrompt: basePrompt, prompt: prompt } }];

// The end frame for the GATE's regeneration, mirroring `End Frame Prompt` on
// the batch path — see that node for why an end frame exists at all, and for
// the full argument behind the opt-in default below.
//
// OFF BY DEFAULT SINCE 2026-09-14, exactly like the batch path: this chain
// runs only when a project's Editing Options says `"endFrame": true`. The two
// copies must keep agreeing about that as much as about the prompt text — a
// regenerated clip built under different rules from its neighbours' is a new
// inconsistency, which is the trap `Prep Video Regen` already warns about for
// the model choice.
//
// Two things make this copy different rather than a duplicate.
//
// First, THE PAYLOAD HAS TO SURVIVE. `Submit Video Regen` reads `$json`, not
// a node reference (which is why both guards around it re-feed the payload),
// so every node between `Prep Video Regen` and the submit must pass the whole
// payload through untouched. Hence Object.assign rather than a fresh object.
//
// Second, and better: `motionPrompt` here may already carry the producer's
// own correction. `Evaluate Video Approval` appends "ADJUSTMENT REQUEST — the
// new video MUST follow this: <Observații Scenă>" when they typed one. So on
// exactly the failure that started this — "mașina iese din curte" — the note
// they wrote is what the end frame is drawn from. That is the strongest
// version of this feature there is: the after-picture is composed from the
// human's description of what went wrong. It is also the strongest remaining
// case for ever switching this back on, and it is still a case, not evidence.
const p = $json; // Prep Video Regen: {id, motionPrompt, imageId, voiceUrl, model, seed, takes}
const rb = $('Receive Batch Input').first().json;

// THE GATE, mirrored. (1) OPT-IN, the default since 2026-09-14; (2)
// sd.endFrameOffAt, the six-hour cooldown stamped by `Submit Cooldown Guard`
// after Flow rejects a submission carrying an end frame — a separate
// mechanism, left exactly as it was, and what protects a project that HAS
// opted in.
//
// Why opt-in, in short — the long version, with the frame-by-frame and the
// numbers, is in `End Frame Prompt`:
//
//   - The feature went live 2026-09-13 at 16:42, default ON, and was never
//     measured on a real film. CLAUDE.md's open-work says so itself: "None of
//     that is a measurement." The only positive evidence is one synthetic
//     clip on a throwaway workflow whose executions no longer exist.
//   - The producer's very next clip — the café film, the only real batch that
//     has ever run with this on — carried two of the feature's signature
//     artefacts: a prep table cross-dissolving between two independently
//     drawn keyframes whose camera position differs, and a subject walking
//     away and turning back because the interpolator must LAND on the frame
//     it is handed.
//   - The middle road was MEASURED, not argued: a shot-aware "draw it only
//     when it helps" rule, run against the 16 real repaired prompts of that
//     film, drew an end frame on 0 of 16
//     (`db/port/motion-permanence/endframe/`). It is a global off switch
//     wearing a heuristic's clothes, so it ships as an off switch.
//   - The structural reason: rule 6 (a) mandates a named camera move on every
//     single shot, and a moving camera guarantees two independently drawn
//     keyframes disagree about where the static set is.
//   - Off restores the behaviour that made ~18 accepted films, with the
//     contradictory continuity clause — the actual cause of the reversing car
//     — already removed twelve minutes BEFORE this shipped.
//
// THIS IS A REVERSAL OF A SAME-DAY CHANGE, NOT A CONSIDERED ROLLOUT. What
// would turn it back on is a measured A/B on one real film: the same scenes
// regenerated with and without an end frame, watched side by side. Nothing
// here is deleted and the trial costs one project setting.
const OFF_FOR_MS = 6 * 60 * 60 * 1000;
const sd = $getWorkflowStaticData('global');
const offUntil = Number(sd.endFrameOffAt || 0) + OFF_FOR_MS;
const off = Date.now() < offUntil;
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }
const optedIn = opts.endFrame === true;
const wanted = optedIn && !off;

const startImage = p.imageId || '';
const motion = String(p.motionPrompt || '').trim();

// 2026-09-14: `look` IS GONE, and with it the `$('Fetch Scene Videos')`
// lookup that existed solely to feed it — it had no other reader in this
// node, so if the clause is ever restored the lookup has to come back with
// it. It read `Imagine First Frame` / `Prompt Vizual` off the scene row the
// gate had already fetched and appended "The shot was originally composed as:
// …". `reference_1` below already carries that composition pixel-for-pixel,
// so restating it in words only anchored the "after" onto the "before": the
// model was shown the first frame, told in prose what the first frame looks
// like, and asked for the last one. The picture that comes back is too close
// to the start frame, which leaves the interpolator eight seconds to fill and
// no distance to cover. The motion — here, the producer's own correction — is
// the only thing that should describe the difference between the two frames.

if (!wanted || !startImage || !motion) {
  // The opt-in reason is reported FIRST when it applies: since 2026-09-14 it
  // is the reason nearly every skip has, and a log line blaming a Flow
  // rejection that never happened sends the next session hunting a phantom.
  // The opt-in test is strict `=== true` on purpose: the fail-safe direction is
  // OFF, so anything ambiguous stays off. But there is NO UI for this key —
  // `grep -rn endFrame platform/` is empty — so hand-edited JSON is the only way
  // in, and `"endFrame": "true"` (a string) is the likely first attempt. That
  // would be silently off while the JSON visibly says true, so the reason echoes
  // what was actually seen rather than asserting the key is absent.
  const seen = JSON.stringify(opts.endFrame);
  const why = !wanted ? (!optedIn ? 'end frames are opt-in since 2026-09-14 — Editing Options has endFrame=' + seen + ', needs the boolean true' : 'end frames paused until ' + new Date(offUntil).toISOString() + ' after a Flow rejection') : (!startImage ? 'no start frame' : 'no motion prompt');
  console.log('RG ENDFRAME ' + p.id + ': skipped, ' + why);
  return [{ json: Object.assign({}, p, { efOk: false, efReason: why }) }];
}

const aspect = rb.Aspect_Ratio === '9:16' ? '9:16' : '16:9';

// Word for word the batch path's prompt. The two must keep agreeing: a
// regenerated clip whose end frame was composed under different rules from
// its neighbours' is a new inconsistency, which is the trap `Prep Video
// Regen` already warns about for the model choice.
//
// 2026-09-14: the camera-move licence is gone from both copies in the same
// edit. The middle sentence used to end "…and whatever the camera move has
// brought into or out of view" — the clause that let the two keyframes
// disagree about where the static set is, on every shot, because rule 6 (a)
// mandates a camera move on every shot. The producer's prep table popping out
// of frame and back in a different place IS that clause, rendered. The set is
// now pinned: only the moving subject may differ.
//
// The same honest caveat as the batch copy: "the frame stays exactly where the
// reference put it" pins the CAMERA too, so an opted-in end frame depicts a
// camera that never moved while the motion string still opens with a mandated
// named move. That is a deliberate choice, not an oversight — a keyframe pair
// that disagrees about the set is a guaranteed artefact, a terminal frame that
// under-describes the camera is only a hint the model can overrule — and it is
// why the feature is opt-in from today rather than tuned.
const prompt = [
  'This is the FINAL FRAME of a single continuous shot: the same camera, the same subject and the same place as the reference image, a few seconds later, after the following motion has fully completed:',
  motion,
  'Draw the world exactly as the reference image shows it — same characters, same faces, same wardrobe, same vehicles and objects, same setting, same lighting and time of day, same lens and framing style. The ONLY thing that may differ is where the moving subjects have got to: every fixed part of the set — walls, furniture, fittings, doors, signage, parked vehicles, anything nobody touches — stays in exactly the position, size and angle the reference shows it in, and the frame stays exactly where the reference put it. Do not restage the shot, do not change the angle for effect, do not add or remove anyone, and do not put any text on the image.',
].filter(Boolean).join(' ');

const efRequest = {
  email: rb.Flow_Email || 'fermafabiz@gmail.com',
  model: 'nano-banana-2',
  prompt: prompt,
  aspectRatio: aspect,
  count: 1,
  captchaRetry: 1,
  reference_1: startImage,
};

console.log('RG ENDFRAME ' + p.id + ': drawing the after-frame from ' + startImage);
return [{ json: Object.assign({}, p, { efOk: true, efRequest: efRequest }) }];

// Read the end frame out of the Flow response and hand the payload on — and
// never throw. Mirrors `Attach End Frame` on the batch path.
//
// The payload is re-emitted whole because `Submit Video Regen` reads `$json`.
// `endImage` rides along on it AND is read back by the submit through
// $('RG Attach End Frame') with a scene-id guard, which is what makes it
// survive the two guards that loop back into the submit: both of them
// re-feed `Prep Video Regen`'s payload, which has no end frame on it.
const p = (() => { try { return $('RG End Frame Prompt').first().json || {}; } catch (e) { return {}; } })();

let endImage = '';
let why = '';
try {
  const resp = $json || {};
  if (resp.error) {
    why = String(resp.error.message || resp.error.description || resp.error).slice(0, 200);
  } else {
    const gi = (((resp.media || [])[0] || {}).image || {}).generatedImage || {};
    endImage = gi.mediaGenerationId || '';
    if (!endImage) why = 'no mediaGenerationId in response: ' + JSON.stringify(resp).slice(0, 200);
  }
} catch (e) {
  why = 'unreadable response: ' + String(e && e.message || e).slice(0, 200);
}

if (endImage) console.log('RG ENDFRAME ' + p.id + ': got ' + endImage);
else console.log('RG ENDFRAME ' + p.id + ': none, falling back to start frame only — ' + why);

return [{ json: Object.assign({}, p, { sceneId: p.id, endImage: endImage, efError: why }) }];

// The motion judge for the GATE's regeneration, mirroring `Motion Prep` on
// the batch path — see that node for why a clip is judged at all.
//
// It matters MORE here, not less. A producer who rejected a clip because the
// car drove the wrong way clicks regenerate, waits a minute and a half, and
// is handed another one. Catching that before they see it is the whole point,
// and the brief this judges against is better too: `Evaluate Video Approval`
// appends their own "ADJUSTMENT REQUEST — the new video MUST follow this:
// …" to the motion prompt, so what the clip is measured against is what the
// human actually asked for.
//
// 2026-09-13 — mirrored onto this node the two changes made to `Motion Prep`
// after the café-stockroom clip the producer rejected: a held object
// vanishing, the same reach performed twice, papers taped to a fridge
// flapping indoors, a fridge door opening by itself, the subject walking away
// and turning back. The old three-question judge would have scored that clip
// a clean pass, because nothing it asked about was wrong.
//
//   1. The question now also asks for "permanence", "untouched" and "loop",
//      and `RG Motion Verdict` reads all three. The wording is spliced from
//      the batch node word for word, as it always was — INCLUDING the two
//      carve-outs: a thing that leaves frame because the camera moved has not
//      vanished (every shot has a camera move, so an absolute question would
//      dock good pans), and outdoors wind, water, foliage, traffic and crowds
//      move untouched and that is correct (or the gate re-rolls street scenes
//      for being streets).
//   2. The brief handed to the judge is the ACTION ONLY. Scenes written
//      before today carry roughly 355 characters of "Negative: …"
//      prohibitions at the end of `Video Scenă URL`; asking "does the clip do
//      what the brief says" while calling that list the brief measured the
//      clip against things that were never meant to happen, and with the
//      `motion.slice(0, 700)` below it could crowd the real action out of the
//      question altogether. The strip is the one already live in
//      `Current Scene`, `End Frame Prompt` and `Submit Video Regen`.
const ev = $json; // Extract Regen Video URL: {Video_Signed_URL, Video_Media_Id}
const p = $('Prep Video Regen').first().json;
const sd = $getWorkflowStaticData('global');
sd.motionRerolls = sd.motionRerolls || {};

// Keyed 'regen:<id>' the way the cooldown counters already are, so a scene
// that used its batch re-roll still gets one here — these are different
// takes, judged against different briefs. `Sort & Cap Scenes` deliberately
// does NOT clear these keys when it resets the batch ones, because it runs on
// every regen cycle and a wholesale reset would make MAX_REROLLS meaningless
// here.
const key = 'regen:' + p.id;
const MAX_REROLLS = 1;
let opts = {};
try { opts = JSON.parse((($('IMG Load Project').first().json.fields || {})['Editing Options']) || '{}') || {}; } catch (e) { opts = {}; }

// Strip the legacy tail, but NOT the producer's request — this is the one
// copy of the strip that cannot be a single split. `Evaluate Video Approval`
// builds motionPrompt as `Video Scenă URL` + ' ADJUSTMENT REQUEST — the new
// video MUST follow this: …', APPENDED, so on a scene written before today
// the producer's own words sit on the far side of the "Negative:" tail.
// Splitting the whole string there would throw away the one sentence this
// regeneration exists to satisfy. Cut the request off first, apply the
// canonical strip to the stored half, then put the request back.
const rawMotion = String(p.motionPrompt || '');
const adjAt = rawMotion.search(/\s*ADJUSTMENT REQUEST\b/i);
const storedMotion = adjAt >= 0 ? rawMotion.slice(0, adjAt) : rawMotion;
const adjustment = adjAt >= 0 ? rawMotion.slice(adjAt).trim() : '';
const motion = (String(storedMotion).split(/\s*Negative:\s*/i)[0].trim() + (adjustment ? ' ' + adjustment : '')).trim();

const done = (sd.motionRerolls[key] || 0) >= MAX_REROLLS;
const skip = opts.motionJudge === false ? 'motionJudge: false'
  : (!ev.Video_Signed_URL ? 'no signed clip URL to inspect'
  : (!motion ? 'no motion prompt to judge against'
  : (done ? 'already re-rolled ' + MAX_REROLLS + ' time(s)' : '')));

const base = { sceneId: p.id, key: key, ord: p.id, videoUrl: ev.Video_Signed_URL || '', mediaId: ev.Video_Media_Id || '', passthrough: ev };
if (skip) {
  console.log('RG MOTION ' + p.id + ': not judged, ' + skip);
  return [{ json: Object.assign({}, base, { ok: false, reason: skip }) }];
}

// Word for word the batch path's question. The two must keep agreeing.
const system = 'You are a film editor checking whether a generated shot does what its brief said. You are shown a contact sheet: frames sampled at a fixed interval across a single 8-second clip, in time order, left to right and then top to bottom. The frames are samples, not the whole clip: a fault shorter than the gap between two of them is invisible here, so judge what you can actually see and do not infer what happened in between. Judge only what the brief claims and whether the world holds together. Do not judge taste, style, beauty, lighting or composition. Answer only the JSON object requested.';
const ask = [
  'The brief for this shot was:',
  '"' + motion.slice(0, 700) + '"',
  'Score each 0 to 1.',
  '"direction": does the movement across the frames match what the brief says, including which way things travel and whether they approach or leave? 1 = it does what the brief says; 0 = it does the opposite (the brief says out and the subject goes in, or the brief says left to right and it goes right to left). If the brief names no direction, answer 1.',
  '"permanence": does everything keep its identity and stay present from the first frame to the last? Lower it when something a character is holding disappears from their hands, when a prop or a piece of furniture vanishes and later comes back, when clothing changes between frames, or when a person or object duplicates. Judge only what the frames can actually show: a thing that leaves the frame because the CAMERA moved, or passes behind something else, has not vanished, and every shot here has a camera move. If you simply cannot follow an object, answer 1 rather than guess. 1 = nothing that should still be visible appears or disappears.',
  '"untouched": does everything that cannot move by itself hold still? Lower it when a door, a drawer, a lid or a window opens or closes with no hand on it, when paper, cloth, curtains or hanging signs move INDOORS where there is no wind, or when an object slides with nothing pushing it. This question is about interiors and about objects with no motive power of their own: outdoors, wind, weather, water, foliage, traffic, animals and crowds move on their own and that is correct, so answer 1 for an exterior unless a door, a lid, a drawer or a piece of furniture moves with nobody near it. 1 = nothing moved that had no cause.',
  '"coherent": does the sequence hold together physically? Lower it when solid things pass through each other, when something floats or sinks into the ground, or when a moving vehicle has no driver.',
  '"morph": true if the frames do not show real movement but a dissolve or warp between two different pictures — the subject changing shape, sliding without turning its wheels or legs, or the scene cross-fading. Otherwise false.',
  '"loop": true if the clip fills its eight seconds by repeating or doubling back — the subject performs the same action twice, or walks out of frame and returns to where it started, or the camera travels somewhere and comes back. Otherwise false.',
  'Answer ONLY JSON: {"direction": number, "permanence": number, "untouched": number, "coherent": number, "morph": boolean, "loop": boolean, "problems": ["short concrete reason", ...]}',
].join(' ');

console.log('RG MOTION ' + p.id + ': judging');
return [{ json: Object.assign({}, base, { ok: true, system: system, ask: ask, motion: motion }) }];

// Keep the regenerated clip, or spend one more generation on it. Mirrors
// `Motion Verdict`; every way of not getting an answer KEEPS the take,
// because a judge that can strand the producer's regeneration by being
// unavailable is worse than no judge.
//
// 2026-09-13 — `RG Motion Prep` now asks three more questions, so this node
// reads three more answers. A score nobody acts on is worse than no score:
// the café-stockroom clip failed on exactly these and on nothing the old
// three questions covered.
//
//   "permanence" — a held object vanishing, a prop popping out and back,
//     clothing changing, the subject duplicating.
//   "untouched" — a fridge door and a room door opening by themselves, taped
//     up paper flapping in a wind that cannot exist indoors.
//   "loop" — the eight seconds filled by doing the same thing twice, or by
//     walking out of frame and coming back to where it started.
//
// The two rules the old checks follow are kept for the new ones. A MISSING
// score is NOT a failure: `num()` leaves it null, the comparison is skipped
// and the clip is kept, so a judge answering in the old shape (or a model
// that drops a field) can never start re-rolling the producer's takes. And
// the thresholds stay low on purpose — a re-roll costs a whole Veo
// generation and a place in the queue, so this fires only when the judge is
// confident, not when it is unenthusiastic:
//   permanence < 0.5, as strict as direction — an object disappearing out of
//     a hand is unpostable, and it is what was reported;
//   untouched < 0.45, the looser of the two, because it is the check most
//     easily tripped by legitimate motion the judge cannot attribute (a door
//     the subject really did push, a curtain outdoors in real wind).
//   loop is a boolean like morph, but unlike morph it is NOT a reason to drop
//     the end frame — it is a new roll of the dice. It is carried in the
//     re-roll payload anyway so `RG Motion Resubmit` can decide otherwise
//     later without this node changing.
const prep = $('RG Motion Prep').first().json;
const sd = $getWorkflowStaticData('global');
sd.motionRerolls = sd.motionRerolls || {};
sd.motionNotes = sd.motionNotes || {};
const MAX_REROLLS = 1;

// The ORIGINAL Extract Regen Video URL item flows on — Download Regen Clip
// and everything after it read Video_Signed_URL / Video_Media_Id.
const keep = (why) => [{ json: Object.assign({}, prep.passthrough || {}, { motionVerdict: why, motionReroll: false }) }];

if (!prep.ok) return keep(prep.reason || 'not judged');

let v = null;
try {
  const text = (($json.choices || [])[0] || {}).message ? String((($json.choices || [])[0] || {}).message.content || '') : '';
  const m = text.match(/\{[\s\S]*\}/);
  v = m ? JSON.parse(m[0]) : null;
} catch (e) { v = null; }
if (!v) {
  console.log('RG MOTION ' + prep.sceneId + ': unreadable judge answer, keeping — ' + JSON.stringify($json).slice(0, 200));
  return keep('unreadable');
}

const num = (x) => (typeof x === 'number' && isFinite(x)) ? x : null;
const direction = num(v.direction);
const permanence = num(v.permanence);
const untouched = num(v.untouched);
const coherent = num(v.coherent);
const morph = v.morph === true;
const loop = v.loop === true;
const problems = Array.isArray(v.problems) ? v.problems.map(String).slice(0, 4) : [];

const bad = [];
if (direction !== null && direction < 0.5) bad.push('direction ' + direction);
if (permanence !== null && permanence < 0.5) bad.push('permanence ' + permanence);
if (untouched !== null && untouched < 0.45) bad.push('untouched ' + untouched);
if (coherent !== null && coherent < 0.45) bad.push('coherence ' + coherent);
if (morph) bad.push('morph');
if (loop) bad.push('loop');

const summary = 'direction=' + direction + ' permanence=' + permanence + ' untouched=' + untouched + ' coherent=' + coherent + ' morph=' + morph + ' loop=' + loop + (problems.length ? ' — ' + problems.join('; ') : '');
const n = sd.motionRerolls[prep.key] || 0;
if (!bad.length) { console.log('RG MOTION ' + prep.sceneId + ': ok, ' + summary); return keep('ok'); }
if (n >= MAX_REROLLS) { console.log('RG MOTION ' + prep.sceneId + ': still wrong after ' + n + ' re-roll(s), keeping it (' + bad.join(', ') + '): ' + summary); return keep('wrong-accepted'); }

sd.motionRerolls[prep.key] = n + 1;
sd.motionNotes[prep.key] = (bad.join(', ') + (problems.length ? ': ' + problems.join('; ') : '')).slice(0, 400);
console.log('RG MOTION ' + prep.sceneId + ': re-roll ' + (n + 1) + '/' + MAX_REROLLS + ' (' + bad.join(', ') + '): ' + summary);
return [{ json: { sceneId: prep.sceneId, key: prep.key, motionReroll: true, morph: morph, loop: loop, attempt: n + 1, problems: bad, discardedMediaId: prep.mediaId } }];

// Back to Submit Video Regen for one more take — differently, and carrying
// the payload, because that node reads `$json` (the reason both guards around
// it re-feed `Prep Video Regen`'s output).
//
// A plain resubmit would return the same clip: `Prep Video Regen` derives the
// seed from the scene id and the takes already FILED, and a take rejected by
// the judge is never filed. See `Motion Resubmit` on the batch path for the
// same reasoning and for why morph is the one verdict a new seed cannot fix.
const v = $json; // RG Motion Verdict, reroll branch
const p = $('Prep Video Regen').first().json;
const sd = $getWorkflowStaticData('global');

// The previous take already spent some of this scene's poll budget; without
// this the new job could be declared timed out on arrival. `Regen Resubmit
// Guard` does the same.
sd.regenPolls = sd.regenPolls || {};
sd.regenPolls[p.id] = 0;

const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const seed = hash(String(p.id) + ':rgmotion:' + v.attempt) % 2147483647;
const dropEndFrame = v.morph === true;

// 2026-09-14 — THE RE-ROLL NOW CARRIES WHAT THE JUDGE FOUND. The whole
// argument is written out in `Motion Resubmit` on the batch path and is not
// repeated here: the short of it is that the judge writes FAULTS ("the sleeve
// stack disappears from her hands"), and quoting a fault into a Veo prompt is
// the exact anti-pattern 2026-09-13 was spent removing, so the SIGNAL — never
// the sentence — is mapped to a positive requirement by a fixed literal table
// that cannot smuggle a negation.
//
// LOCKSTEP PAIR WITH `Motion Resubmit`: CLAUSES, SIGNAL_ORDER, MAX_CLAUSES,
// LEAD_IN and UNSAFE are byte-identical there and must stay so. A rescued
// clip corrected by a different director from its neighbours is a new
// inconsistency, which is the same rule `Prep Video Regen` already follows
// for the model choice.
const CLAUSES = {
  permanence: 'Whatever the subject is holding stays in their hands for the whole shot and is there in the final frame; every prop, garment and piece of furniture keeps the shape, colour and cut it has in the opening frame.',
  untouched: 'Every door, drawer, lid, window and taped-up sheet of paper stays exactly as the opening frame shows it, and moves only in the instant a hand moves it; indoors the air is still.',
  loop: 'One single continuous action, performed once and carried straight through to the final frame; the subject ends the take somewhere new, further along than it began.',
  direction: 'Everything that travels keeps the one direction the action above names and holds that heading to the final frame; the camera keeps the move it was given and travels that way throughout.',
  coherence: 'Solid things keep their own space: feet stay on the ground, people and vehicles pass around each other, and every vehicle that moves has a driver at its controls.',
  morph: 'Everything that changes on screen changes because something physically moves — wheels turn, legs step, hands travel — and every shape keeps its own edges for the whole take.',
};
const SIGNAL_ORDER = ['permanence', 'untouched', 'loop', 'direction', 'coherence', 'morph'];
const MAX_CLAUSES = 3;
const LEAD_IN = 'CORRECTION — the new take MUST hold to this: ';
const UNSAFE = /\b(?:no|not|never|none|nothing|nobody|nor|without|avoid\w*|prevent\w*|stop\w*|remove\w*|don't|doesn't|isn't|aren't|disappear\w*|vanish\w*|duplicat\w*|morph\w*|warp\w*|flicker\w*)\b/i;

// `RG Motion Verdict` sends `problems` as the GATE list ("permanence 0.3"),
// not the judge's prose — that only ever reaches `sd.motionNotes`. Read the
// first word; re-check morph/loop off their own booleans so a partial or
// older verdict payload still corrects what it can.
const fired = [];
const seen = (Array.isArray(v.problems) ? v.problems : []).map((x) => String(x).trim().split(/\s+/)[0].toLowerCase());
if (v.morph === true) seen.push('morph');
if (v.loop === true) seen.push('loop');
seen.forEach((k) => { if (CLAUSES[k] && fired.indexOf(k) < 0) fired.push(k); });

const withheld = fired.filter((k) => UNSAFE.test(CLAUSES[k]));
if (withheld.length) console.log('RG MOTION ' + p.id + ': clause withheld, a negation reached the map — ' + withheld.join(', '));
const used = SIGNAL_ORDER.filter((k) => fired.indexOf(k) >= 0 && withheld.indexOf(k) < 0).slice(0, MAX_CLAUSES);
const correction = used.length ? LEAD_IN + used.map((k) => CLAUSES[k]).join(' ') : '';

// WHERE THE CORRECTION LANDS, and why this path differs from the batch.
//
// The two paths compose the prompt in different places, and that difference
// is what decides where the correction goes. `Current Scene` composes the
// batch prompt once into `videoRequest.prompt` and freezes it, so
// `Motion Resubmit` has to hand `Submit Video` a whole replacement prompt.
// Here the guardrails are composed by `Submit Video Regen` ITSELF on every
// submit, around `$json.motionPrompt` — so the correction only has to join
// the ACTION, and it lands in exactly the slot the producer's own
// "ADJUSTMENT REQUEST — the new video MUST follow this: …" lands in from
// `Evaluate Video Approval`. Nothing has to be duplicated, and no fourth
// copy of WORLD_RULES appears in this repo.
//
// The insert is still at the first `Negative:` boundary rather than an
// append: `Evaluate Video Approval` strips the legacy tail before it hands
// this over, but it FALLS BACK to the raw stored string on a tail-only row,
// and `Submit Video Regen` cuts at that same token — so an appended
// correction on such a row would be thrown away. A head of nothing means the
// stored prompt was a bare tail, and correcting an empty action would submit
// the correction with no shot at all, so that one case keeps today's
// behaviour: new seed, motion prompt untouched.
const baseMotion = String(p.motionPrompt || '');
let motionPrompt = baseMotion;
if (correction) {
  const cut = baseMotion.search(/\s*Negative\s*:/i);
  const head = (cut >= 0 ? baseMotion.slice(0, cut) : baseMotion).trim();
  const tail = cut >= 0 ? baseMotion.slice(cut) : '';
  if (head) motionPrompt = head + ' ' + correction + tail;
}

console.log('RG MOTION ' + p.id + ': resubmitting with seed ' + seed + (dropEndFrame ? ', WITHOUT the end frame (morph)' : ''));
// Printed on every re-roll, empty correction included — one `grep 'RG MOTION'`
// over an execution has to say whether the correction rode along and which
// clauses, without re-running anything.
console.log('RG MOTION ' + p.id + ': correction ' + (used.length ? '(' + used.join(', ') + ')' : '(none)') + (motionPrompt === baseMotion ? ', prompt unchanged' : ', ' + motionPrompt.length + ' chars'));
// `motionPrompt` overrides the key it inherits from `p`, which is what makes
// the DIRECT edge into Submit Video Regen work with no change to that node.
// `baseMotion` is for the OTHER two edges: `Regen Resubmit Guard` (filter
// refusal) and `Regen Cooldown Guard` (a 429) both re-feed `Prep Video
// Regen`'s payload, so a retry after this re-roll arrives carrying the
// UNCORRECTED prompt while still picking the new seed up out of this node.
// Submit Video Regen's expression closes that by preferring this corrected
// prompt when `$json.motionPrompt` still equals the base it was built from —
// which is also what stops a LATER, separate regeneration of the same scene
// (a fresh producer note, a different `motionPrompt`) from being overwritten
// by this stale correction. Matching on the scene id alone would do exactly
// that, because that node reads this one with `.first()`, i.e. its latest run.
return [{ json: Object.assign({}, p, { sceneId: p.id, seed: seed, dropEndFrame: dropEndFrame, attempt: v.attempt, correction: correction, baseMotion: baseMotion, motionPrompt: motionPrompt }) }];

const item = $input.first().json;
const status = (item.status || '').toLowerCase();
// Polls are counted PER SCENE in static data, not with $runIndex — which
// counts every poll of the execution across all scenes, and a pass now
// covers the whole film (Sort & Cap Scenes resets sd.polls each pass).
// 30s a poll ('Wait Video'); 120 = one hour a clip, sized for the
// low-priority Veo queue. A clip that overruns it is treated as a FAILED
// job — 'Resubmit Guard' resubmits it — rather than killing the film.
const sd = $getWorkflowStaticData('global');
sd.polls = sd.polls || {};
const sceneId = $('Current Scene').first().json.id;
sd.polls[sceneId] = (sd.polls[sceneId] || 0) + 1;
const MAX_POLLS = 120;
const raw = JSON.stringify(item);
const done = status === 'completed' || raw.includes('flow-content.google/video');
let failed = status === 'failed' || status === 'error' || status === 'cancelled';
if (!done && !failed && sd.polls[sceneId] > MAX_POLLS) {
  console.log('Scene ' + sceneId + ': video job still not done after ' + MAX_POLLS + ' polls — treating as failed so it gets resubmitted.');
  failed = true;
  item.error = 'polling timed out after ' + MAX_POLLS + ' polls';
}
// Failed jobs are routed to a resubmit branch instead of throwing here —
// Google intermittently fails generations with VIDEO_GENERATION_TIMED_OUT
// and a resubmit usually succeeds.
return [{ json: Object.assign({}, item, { done: done && !failed, jobFailed: failed }) }];

const item = $input.first().json;
function find(obj, pred) {
  let f = null;
  (function w(o) { if (f) return;
    if (typeof o === 'string') { if (pred(o)) f = o; return; }
    if (Array.isArray(o)) { for (const v of o) { if (f) return; w(v); } return; }
    if (o && typeof o === 'object') { for (const k of Object.keys(o)) { if (f) return; w(o[k]); } }
  })(obj);
  return f;
}
let url = null, mediaId = null;
try { const gv = item.response && item.response.media && item.response.media[0] && item.response.media[0].video && item.response.media[0].video.generatedVideo; if (gv) { if (typeof gv.fifeUrl === 'string') url = gv.fifeUrl; if (typeof gv.mediaGenerationId === 'string') mediaId = gv.mediaGenerationId; } } catch (e) {}
if (!url) url = find(item, s => s.startsWith('http') && s.includes('flow-content.google') && s.includes('/video'));
if (!mediaId) mediaId = find(item, s => s.includes('-video:'));
if (!url && !mediaId) throw new Error('No video url or mediaId in completed job. Head: ' + JSON.stringify(item).slice(0, 800));
return [{ json: { Video_Signed_URL: url || '', Video_Media_Id: mediaId || '' } }];

const sd = $getWorkflowStaticData('global');
sd.prevImageUrl = '';
sd.prevImageId = '';
sd.anchorId = '';
// Every per-scene counter in this workflow lives here and is reset per
// pass: video polls / resubmits (batch loop), regen polls / resubmits (the
// gate), multi-voice polls, motion-prompt rewrites, submit cooldowns.
// They are keyed by scene id because $runIndex counts a node's runs across
// the WHOLE execution — and a pass now covers the whole film.
sd.polls = {};
sd.resubmits = {};
sd.regenPolls = {};
sd.regenResubmits = {};
sd.multiPolls = {};
sd.rewrites = {};
sd.submitCooldowns = {};
sd.imgRewrites = {};
sd.imgCooldowns = {};
sd.consistencyRerolls = {};
sd.consistencyNotes = {};
sd.muxPolls = {};
// 2026-09-14 — the motion judge's two counters were missed when that feature
// went live the day before, so `MAX_REROLLS = 1` meant one re-roll per scene
// for the LIFE OF THE n8n PROCESS rather than one per pass: a scene that spent
// its re-roll on one film could never earn another. `consistencyRerolls` and
// `consistencyNotes` above are the still-image judge's exact analogues and have
// always been reset here; these two belong beside them, and the comment at the
// top of this block already claims that EVERY per-scene counter lives here.
//
// NOT wholesale, though, and that is the whole subtlety. This node runs on
// every REGEN cycle as well as every batch pass — `If Video Regen Pending` →
// `Fetch Approved Scenes` → `Warm-up Cooldown` → here — and `RG Motion Prep`
// keys the SAME object as 'regen:<scene id>'. Clearing it outright would reset
// the regen counter on every cycle and hand each regenerated scene an unlimited
// supply of re-rolls, a whole Veo generation apiece. So reset only the BATCH
// keys and leave the 'regen:' ones to the gate that owns them.
sd.motionRerolls = sd.motionRerolls || {};
sd.motionNotes = sd.motionNotes || {};
for (const k of Object.keys(sd.motionRerolls)) if (!k.startsWith('regen:')) delete sd.motionRerolls[k];
for (const k of Object.keys(sd.motionNotes)) if (!k.startsWith('regen:')) delete sd.motionNotes[k];
const items = $input.all().slice();
const ord = it => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
// "Done" is judged on the CLIP and the regen flags, never on the status
// text. It used to be the text ('Așteaptă Aprobare Video' / 'Finalizat'),
// and `VP Apply` stamped exactly that text on a scene whose clip had just
// been REFUSED by the video filter — so a refused scene sorted as finished,
// fell behind the cap on any film longer than 8 scenes, and was never
// generated again (Vegas, 71 scenes: 117, 118, 203 and 204 sat like that).
const pending = it => {
  const f = it.json.fields || {};
  const hasClip = String(f['Scene Final URL'] || '').startsWith('http');
  const flagged = f['Regenerează Video'] === true || f['Regenerează Imagine'] === true || f['Regenerează Voce'] === true;
  return !hasClip || flagged;
};
items.sort((a, b) => {
  const pa = pending(a), pb = pending(b);
  if (pa !== pb) return pa ? -1 : 1;
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
